/*******************************************************************************************************
* The code from this section is executed once the form is loaded.                                      *
*                                                                                                      *
* Depending on the stage of the form lifecycle when a particular action should be performed,           *
* you can use on the following hooks:                                                                  *
*                                                                                                      *
* fd.rendered()     the code is executed once the form is rendered                                     *
*                                                                                                      *
* fd.beforeSave()   the code is executed right before saving the form. If returns Promise, the saving  *
*                   does not proceed until the Promise is resoved. If the Promise is rejected,         * 
*                   the saving interrupts. This is the appropriate place for adding custom validation. *
*                                                                                                      *
* fd.saved()        the code is executed once the form is submitted                                    *
*                                                                                                      *
* The following predefined variables can be utilized in the code:                                      *
*                                                                                                      *
* fd    an instance of the current form                                                                *
* $     jQuery object                                                                                  *
*                                                                                                      *
*******************************************************************************************************/

fd.rendered(function () {

    const wizardContainer = fd.container('Wizard1');
    if (!wizardContainer) return;

    const wizard = wizardContainer.widget;
    const originalTabs = wizard.tabs.slice();

    /*
     * PAGE INDEXES
     *
     * Kept exactly as they appear in the original code.
     * See the note below regarding inconsistencies.
     */
    const PAGE = {
        CHILD1_ELIGIBILITY: 2,
        ADD_CHILD2_STOP: 6,

        CHILD2_ELIGIBILITY: 12,
        ADD_CHILD3_STOP: 8,

        CHILD3_ELIGIBILITY: 22,
        ADD_CHILD4_STOP: 10,

        CHILD4_ELIGIBILITY: 32,

        ADD_CHILD2: 11,
        ADD_CHILD3: 21,
        ADD_CHILD4: 31,
        PARENT_DETAILS: 41
    };


    // ------------------------------------------------------------
    // Fields
    // ------------------------------------------------------------

    const child2Fields = [
        'Child2_FirstName',
        'Child2_LastName',
        'Child2_DateOfBirth',
        'Child2_GPSurgery'
    ];

    const child3Fields = [
        'Child3_FirstName',
        'Child3_LastName',
        'Child3_DateOfBirth',
        'Child3_GPSurgery'
    ];

    const child4Fields = [
        'Child4_FirstName',
        'Child4_LastName',
        'Child4_DateOfBirth',
        'Child4_GPSurgery'
    ];


    // ------------------------------------------------------------
    // "Add another child?" rules
    // ------------------------------------------------------------

    const addChildRules = {
        AddChild2: {
            page: PAGE.ADD_CHILD2_STOP,
            keepTabs: 7,
            optionalFields: [
                ...child2Fields,
                ...child3Fields,
                ...child4Fields,
                'AddChild3',
                'AddChild4'
            ]
        },

        AddChild3: {
            page: PAGE.ADD_CHILD3_STOP,
            keepTabs: 9,
            optionalFields: [
                ...child3Fields,
                ...child4Fields,
                'AddChild4'
            ]
        },

        AddChild4: {
            page: PAGE.ADD_CHILD4_STOP,
            keepTabs: 11,
            optionalFields: [
                ...child4Fields
            ]
        }
    };


    // Remember original required state so it can be restored
    const originalRequired = {};

    Object.values(addChildRules).forEach(function (rule) {
        rule.optionalFields.forEach(function (fieldName) {
            const field = fd.field(fieldName);

            if (field && originalRequired[fieldName] === undefined) {
                originalRequired[fieldName] = field.required;
            }
        });
    });


    function setFieldsOptional(fieldNames) {
        fieldNames.forEach(function (fieldName) {
            const field = fd.field(fieldName);

            if (field) {
                field.required = false;
            }
        });
    }


    function restoreRequiredFields(fieldNames) {
        fieldNames.forEach(function (fieldName) {
            const field = fd.field(fieldName);

            if (
                field &&
                Object.prototype.hasOwnProperty.call(
                    originalRequired,
                    fieldName
                )
            ) {
                field.required = originalRequired[fieldName];
            }
        });
    }


    function restoreWizard() {
        if (wizard.tabs.length === originalTabs.length) {
            return;
        }

        const currentIndex = wizard.activeTabIndex;

        wizard.tabs = originalTabs.slice();
        wizard.reset();

        // reset() returns the wizard to index 0
        window.setTimeout(function () {
            wizard.changeTab(0, currentIndex);
        }, 0);
    }


    function checkAddChild(fieldName) {
        const field = fd.field(fieldName);
        const rule = addChildRules[fieldName];

        if (!field || !rule) return;

        // Only manipulate the wizard while we're on
        // the relevant "Add child" page.
        if (wizard.activeTabIndex !== rule.page) {
            return;
        }

        if (field.value === 'No') {

            // End the wizard at this page
            wizard.tabs = originalTabs.slice(0, rule.keepTabs);

            setFieldsOptional(rule.optionalFields);

        } else if (field.value === 'Yes') {

            restoreRequiredFields(rule.optionalFields);
            restoreWizard();
        }
    }


    // Monitor AddChild fields
    Object.keys(addChildRules).forEach(function (fieldName) {
        const field = fd.field(fieldName);

        if (field) {
            field.$on('change', function () {
                checkAddChild(fieldName);
            });
        }
    });


    // ------------------------------------------------------------
    // Eligibility redirects
    // ------------------------------------------------------------

    const eligibilityRedirects = {
        2: {
            child: 'Child1',
            target: PAGE.ADD_CHILD2
        },

        12: {
            child: 'Child2',
            target: PAGE.ADD_CHILD3
        },

        22: {
            child: 'Child3',
            target: PAGE.ADD_CHILD4
        },

        32: {
            child: 'Child4',
            target: PAGE.PARENT_DETAILS
        }
    };


    // ------------------------------------------------------------
    // ONE wizard change event
    // ------------------------------------------------------------

    wizard.$on('on-change', function (prevIndex, newIndex) {

        // Check for eligibility redirect
        const redirect = eligibilityRedirects[prevIndex];

        if (
            redirect &&
            eligibilityStatus[redirect.child] &&
            eligibilityStatus[redirect.child].varChildEligible === false
        ) {
            window.setTimeout(function () {

                // The wizard has already changed to newIndex,
                // therefore newIndex is the current/source page.
                wizard.changeTab(newIndex, redirect.target);

            }, 100);

            return;
        }


        // Apply AddChild rule when arriving at its page
        Object.keys(addChildRules).forEach(function (fieldName) {
            checkAddChild(fieldName);
        });
    });


    // ------------------------------------------------------------
    // Initial state
    // ------------------------------------------------------------

    Object.keys(addChildRules).forEach(function (fieldName) {
        checkAddChild(fieldName);
    });

});

